examples:
包装异常：
void doSomething() {
    try {
        throw std::runtime_error{"Throwing a runtime_error exception"};
    } catch (const std::runtime_error& e) {
        std::cout << "doSomething caught a runtime_error" << std::endl;
        std::cout << "doSomething throwing MyException" << std::endl;
        std::throw_with_nested(MyException{"MyException with nested runtime_error"});
    }
}

使用 rethrow_nested() 处理内部异常：
try {
    doSomething();
} catch (const MyException& e) {
    const auto* nested = dynamic_cast<const std::nested_exception*>(&e);
    if (nested) {
        try {
            nested->rethrow_nested();
        } catch (const std::runtime_error& e) {
            std::cout << "Nested exception: " << e.what() << std::endl;
        }
    }
}

也可以使用：
try {
    std::rethrow_if_nested(e);
} catch (const std::runtime_error& e) {
    // 处理内部异常
}
